+// Concurrent spends must never take a tenant past its limit: the check and
+// the increment have to be atomic.
+func TestSpendAllNeverExceedsLimit(t *testing.T) {
+	for round := 0; round < 200; round++ {
+		l := NewLedger(map[string]int{"acme": 100})
+		spends := make([]int, 50)
+		for i := range spends {
+			spends[i] = 10
+		}
+		if got := l.SpendAll("acme", spends); got != 10 {
+			t.Fatalf("round %d: SpendAll ok = %d, want exactly 10 (limit 100 / 10)", round, got)
+		}
+		if got := l.Remaining("acme"); got != 0 {
+			t.Fatalf("round %d: remaining = %d, want 0", round, got)
+		}
+	}
+}
+
+// Same invariant with uneven spend sizes: the successful total never exceeds
+// the limit and matches what the ledger recorded.
+func TestConcurrentSpendTotalWithinLimit(t *testing.T) {
+	const limit = 1000
+	for round := 0; round < 100; round++ {
+		l := NewLedger(map[string]int{"acme": limit})
+		var wg sync.WaitGroup
+		var mu sync.Mutex
+		total := 0
+		for i := 0; i < 64; i++ {
+			n := 7 + i%13*5
+			wg.Add(1)
+			go func() {
+				defer wg.Done()
+				if l.Spend("acme", n) == nil {
+					mu.Lock()
+					total += n
+					mu.Unlock()
+				}
+			}()
+		}
+		wg.Wait()
+		if total > limit {
+			t.Fatalf("round %d: successful spends total %d > limit %d", round, total, limit)
+		}
+		if got := l.Remaining("acme"); got != limit-total {
+			t.Fatalf("round %d: remaining = %d, want %d", round, got, limit-total)
+		}
+	}
+}

