-func (l *Ledger) Refund(tenant string, n int) {
+// Refund gives n tokens back to tenant. n must be positive, the tenant must be
+// known, and n may not exceed what the tenant has spent: such a refund is
+// rejected with ErrOverRefund (not clamped) and leaves the balance unchanged,
+// so 0 <= spent <= limit always holds.
+func (l *Ledger) Refund(tenant string, n int) error {
+	if n <= 0 {
+		return fmt.Errorf("refund %d tokens: must be positive", n)
+	}
 	l.mu.Lock()
 	defer l.mu.Unlock()
+	if _, ok := l.limit[tenant]; !ok {
+		return fmt.Errorf("tenant %q: unknown", tenant)
+	}
+	if n > l.spent[tenant] {
+		return fmt.Errorf("tenant %q: %w (%d > %d spent)", tenant, ErrOverRefund, n, l.spent[tenant])
+	}
 	l.spent[tenant] -= n
+	return nil
 }

 // Remaining returns the tokens tenant may still spend.
