+// closeCountingTransport wraps a RoundTripper and counts how many response
+// bodies it handed out and how many of them were closed.
+type closeCountingTransport struct {
+	base   http.RoundTripper
+	opened atomic.Int64
+	closed atomic.Int64
+}
+
+func (c *closeCountingTransport) RoundTrip(req *http.Request) (*http.Response, error) {
+	resp, err := c.base.RoundTrip(req)
+	if err != nil {
+		return nil, err
+	}
+	c.opened.Add(1)
+	resp.Body = &countingBody{ReadCloser: resp.Body, closed: &c.closed}
+	return resp, nil
+}
+
+type countingBody struct {
+	io.ReadCloser
+	closed *atomic.Int64
+	once   sync.Once
+}
+
+func (b *countingBody) Close() error {
+	b.once.Do(func() { b.closed.Add(1) })
+	return b.ReadCloser.Close()
+}
